import {
	TECHNICAL_TERM_IMAGE_MAX_BYTES,
	TECHNICAL_TERM_MAX_VIDEOS,
	TECHNICAL_TERM_VIDEO_MAX_BYTES,
} from '@daz-pilot/daz-pilot-backend-api-types';
import type { NextConfig } from 'next';
import { validateEnv } from './src/utils/env';

validateEnv();

const coreBackendUrl = new URL(process.env.NEXT_PUBLIC_CORE_BACKEND_DOMAIN ?? 'http://localhost:4000');

// Server Actions default to 1 MB body limit, which is way below our multipart
// upload contracts (image + up to N videos). Add 10 MB headroom for multipart
// overhead. Keep this aligned with the backend's stream-level guards.
const SERVER_ACTION_BODY_LIMIT_BYTES =
	TECHNICAL_TERM_IMAGE_MAX_BYTES + TECHNICAL_TERM_MAX_VIDEOS * TECHNICAL_TERM_VIDEO_MAX_BYTES + 10 * 1024 * 1024;

const nextConfig: NextConfig = {
	reactCompiler: true,
	images: {
		remotePatterns: [
			{
				protocol: coreBackendUrl.protocol.replace(':', '') as 'http' | 'https',
				hostname: coreBackendUrl.hostname,
				port: coreBackendUrl.port,
				pathname: '/media/**',
			},
		],
	},
	experimental: {
		serverActions: {
			bodySizeLimit: SERVER_ACTION_BODY_LIMIT_BYTES,
		},
	},
	turbopack: {
		root: __dirname,
	},
};

export default nextConfig;

import { schoolSlugSchema, z } from '@daz-pilot/daz-pilot-backend-api-types';

const emptyToUndefined = (value: unknown) => (value === '' ? undefined : value);

export const envSchema = z.object({
	CORE_BACKEND_DOMAIN: z.url(),
	NEXT_PUBLIC_CORE_BACKEND_DOMAIN: z.url(),
	SCHOOL_SLUG: z.preprocess(emptyToUndefined, schoolSlugSchema.optional()),
});

declare global {
	// eslint-disable-next-line @typescript-eslint/no-namespace
	namespace NodeJS {
		// eslint-disable-next-line @typescript-eslint/no-empty-object-type
		interface ProcessEnv extends z.infer<typeof envSchema> {}
	}
}

export const validateEnv = () => {
	const parsed = envSchema.safeParse(process.env);
	if (parsed.success) return;

	console.log(' \x1b[1m\x1b[31m⚠\x1b[0m Environment variables validation failed\n');

	for (const issue of parsed.error.issues) {
		console.error(`   - \x1b[31m${issue.path.join('.')}\x1b[0m: ${issue.message}`);
	}

	console.log();
	process.exit(1);
};

